        "content": "LexiClash — это игра множественной стратегии слов в реальном времени, разработанная LexiClash Ltd, базирующейся в Израиле. Мы создаём привлекательные, образовательные и конкурентные словесные игры для игроков всех возрастов — от молодых учеников до опытных любителей слов — на множестве языков и культур.",
        "content2": "То, что началось как небольшой проект увлечения, выросло в платформу, обслуживающую тысячи игроков по всему миру. Наша команда сочетает глубокую экспертизу в дизайне игры, технологии образования и многоязычной разработке программного обеспечения для предоставления опыта словесной игры, как ни один другой. Мы привержены тому, чтобы каждый сеанс игры был забавным, справедливым и обогащающим."
