        "content2": "Мы строим LexiClash для всех: детей от 6 лет, которые только начинают читать, подростков, ищущих веселый вызов, взрослых, которые хотят держать свой ум в тонусе, и пожилых людей, которые наслаждаются головоломками со словами. Наша цель — создать игру, которая объединяет людей на разных языках, культурах и поколениях — доказывая, что слова действительно универсальны."
