        "content": "LexiClash была основана Охадом Фишером и командой увлечённых любителей словесных игр, инженеров-программистов и специалистов по образованию, базирующихся в Израиле. Мы небольшая, но преданная команда, которая глубоко заботится о создании лучшего опыта многопользовательской словесной игры. Каждый член команды приносит любовь к языку, страсть к технологии и приверженность к созданию игр, которые забавны, справедливы и доступны для всех."
