        "mechanic": "Хаос в улье: липкие клетки и задания на синонимы!",
        "storyline": "С восстановленным первым фрагментом слухи о силе Лексикона достигают Архивов мёда. Королева орфографии охраняет второй фрагмент — вплетённый в липкие словесные сети её улья.",
