        "mechanic": "Штурм конвейера: строй составные слова ради огромных бонусов!",
        "storyline": "Компас Лексикона ведёт в Паровую кузницу. Барон Словостроитель вварил пятый фрагмент в свой Word-Assembly-Matic 3000. Вырвать его можно, только превзойдя барона в инженерии.",
