        "mechanic": "Вавилонская вершина: язык меняется, универсальные слова дают огромные бонусы!",
        "storyline": "Восемь фрагментов гудят одновременно на каждом языке. На вершине вавилонского пика лингвист-мудрец медитирует над девятым фрагментом — осколком, который говорит НА ВСЕХ ЯЗЫКАХ одновременно.",
