        "mechanic": "Последнее слово: ВСЕ механики сразу. Собери УДАР ЛЕКСИКОНА!",
        "storyline": "Девять фрагментов собираются в ключ, открывающий библиотеку дракона — где хранится каждое когда-либо написанное слово. Дракон лексикона охраняет последний фрагмент: титульную страницу оригинального Лексикона. Победи его и восстанови книгу, которая держит всю речь вместе.",
